sys_script.script:
// ImportMap Medic — Weekly Audit Scheduled Job
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function execute() {
    var engine = new x_snc_importmap_medic.ImportMapMedicEngine();
    var result = engine.auditInstance({ mode: 'full' });
    gs.info('ImportMap Medic weekly audit complete. Maps audited: ' + result.mapsAudited +
        ', instance score: ' + result.instanceScore +
        ', findings created: ' + result.findingsCreated +
        ', health scores updated: ' + result.healthScoresUpdated +
        ', trends recorded: ' + result.trendsRecorded +
        ', errors: ' + result.errors.length);
})();
